"""Block lists for the manuscript (classical machine-learning version). All numbers are read from result files."""
import json, sys, os, re
import numpy as np, pandas as pd
W = 'res/'
V = json.load(open(W + 'V.json'))
T1 = json.load(open(W + 'ternary.json')) if os.path.exists(W + 'ternary.json') else {}
TO = json.load(open(W + 'ternary_oceanic.json'))
T2 = json.load(open(W + 'ternary2.json'))
RG = pd.DataFrame(json.load(open(W + 'repeated_grouped.json')))
PC = pd.read_csv(W + 'perm_coherent.csv')
Mo, CI, PD, CAL, AUG, H, RV, LK = V['models'], V['ci'], V['paired'], V['cal'], V['aug'], V['hier'], V['revision'], V['leak']
FIG = 'figs'
classes = ['BABB', 'CAB', 'CFB', 'IAB', 'IOAB', 'MORB', 'OIB', 'OPB']
FULLNAME = {'BABB': 'Back-arc basin basalt', 'CAB': 'Continental arc basalt', 'CFB': 'Continental flood basalt', 'IAB': 'Island arc basalt',
            'IOAB': 'Intra-oceanic arc basalt', 'MORB': 'Mid-ocean ridge basalt', 'OIB': 'Ocean island basalt', 'OPB': 'Oceanic plateau basalt'}
mn_ = lambda s: s.replace('-', '−')
def ms(m, p, k, d=1): a, b = Mo[m][p][k]; return f"{100*a:.{d}f} ± {100*b:.{d}f}"
def mv(m, p, k, d=1): return f"{100*Mo[m][p][k][0]:.{d}f}"
def pv(m, k, d=1): return f"{100*CI[m][k][0]:.{d}f}"
def f3(v, d=1, sign=False):
    f = (lambda x: f"{100*x:+.{d}f}") if sign else (lambda x: f"{100*x:.{d}f}")
    z = lambda s: re.sub(r'^[+-](0\.0+)$', r'\1', s)
    return mn_(f"{z(f(v[0]))} ({z(f(v[1]))} to {z(f(v[2]))})")
def pdf(p, a, b, k): return f3(PD[f'{p}|{a}|{b}'][k], sign=True)
def pct(x, d=0): return f"{100*x:.{d}f}"
D = V['data']; c_ = D['counts']
pcg, pcr = V['per_class']['grouped|LightGBM'], V['per_class']['random|LightGBM']
cmg = V['cm']['grouped|LightGBM']
def conf(i, j): return f"{100*cmg[classes.index(i)][classes.index(j)]/sum(cmg[classes.index(i)]):.0f}%"
def rec(c, p='g'): return f"{100*(pcg if p=='g' else pcr)['recall'][classes.index(c)]:.0f}%"
def rci(c): v = CI['LightGBM']['recall'][c]; return f"{100*v[1]:.0f}–{100*v[2]:.0f}%"
med = RV['medians']; bi = RV['babb_idx']; opb = RV['opb_db']; cg = RV['component_grouped']
rg = RG[RG.model == 'LightGBM']; rgr = lambda c, d=1: f"{100*rg[c].min():.{d}f}–{100*rg[c].max():.{d}f}"
pc_el = PC[PC.kind == 'element'].groupby('item')['drop'].agg(['mean', 'std']); pc_bl = PC[PC.kind == 'block'].groupby('item')['drop'].agg(['mean', 'std'])
pe = lambda it: f"{100*pc_el.loc[it,'mean']:.0f} ± {100*pc_el.loc[it,'std']:.0f}"
pb = lambda it: f"{100*pc_bl.loc[it,'mean']:.0f} ± {100*pc_bl.loc[it,'std']:.0f}"
tl = list(pc_el.sort_values('mean', ascending=False).index[:4])
sel = lambda m, th, k: CAL[m]['sel'][str(th)][k]
A = lambda p, m, meth: AUG[f'{p}|{m}|{meth}']
hx = lambda p, m, s, k='bacc': H[f'{p}|{m}|{s}'][k]
EX = json.load(open(W + 'extra.json')); RP = V['rev_pooled']
SF = TO['same_folds']; tn = TO['nested|oceanic arc / MORB / OIB']; tf = SF['Nb–La–Yb (triple fixed)']
DU = V['dups']; DD = DU.get('dedup', {})
def f3r(v, d=0): return f"{100*v[0]:.{d}f}% (95% interval {100*v[1]:.{d}f}–{100*v[2]:.{d}f}%)"
def rng3(v, d=0): return f"{100*v[1]:.{d}f}–{100*v[2]:.{d}f}"


def ordinal(n): return {1: 'first', 2: 'second', 3: 'third', 4: 'fourth', 5: 'fifth'}.get(n, f'{n}th')
def f3p(v, d=1): return f"{100*v[0]:.{d}f}% ({100*v[1]:.{d}f}–{100*v[2]:.{d}f}%)"
def f3c(v, d=1):
    z = lambda x: re.sub(r'^[+-](0\.0+)$', r'\1', f"{100*x:+.{d}f}")
    return mn_(f"{z(v[0])} [{z(v[1])} to {z(v[2])}]")
def nw(n): return {0: 'none', 1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine', 10: 'ten'}.get(n, str(n))
SUBS = {'SiO2': 'SiO₂', 'TiO2': 'TiO₂', 'Al2O3': 'Al₂O₃', 'Fe2O3t': 'Fe₂O₃ᵗ', 'K2O': 'K₂O', 'Na2O': 'Na₂O'}
def chem(s):
    for k, v in SUBS.items(): s = s.replace(k, v)
    return s
TITLE = "Source-grouped validation of machine-learning classifiers for basalt tectonic setting"

ax_ = A('grouped', 'LightGBM', 'xsource'); CON = AUG['contrasts']
L_ = CI['LightGBM']; h3_ = H['grouped|LightGBM|3']; lgbo = SF['LightGBM, 24 concentrations']
ABSTRACT = (
 f"Machine-learning classifiers assign basalts to tectonic settings with reported accuracies near 90%, but they are usually validated with sample-level random splits, in which analyses of the same lava suites enter both the training and the test data. "
 f"We measure the consequence on a public compilation of {D['n']:,} basalt analyses from eight settings. Thirteen classifiers, from linear discriminant analysis to gradient boosting, are evaluated by random five-fold cross-validation and by source-grouped cross-validation, in which all analyses sharing a reference code are held out together. "
 f"With random splits the best model, LightGBM, reaches {pv('LightGBM','acc_r')}% accuracy and {pv('LightGBM','bacc_r')}% balanced accuracy. With grouped splits it reaches {pv('LightGBM','acc')}% (95% interval {rng3(L_['acc'])}%) and {pv('LightGBM','bacc')}% ({rng3(L_['bacc'])}%), and the other flexible models lose similar amounts. The loss is concentrated in back-arc basin, oceanic plateau and arc basalts. Misclassified back-arc samples are assigned to ridge or arc classes according to the strength of their subduction signature, and some samples carry different labels in the two source databases. "
 f"When the class probabilities are summed into arc, ridge and intraplate groups, balanced accuracy on unseen sources is {pct(h3_['bacc'][0])}%, {pct(h3_['gap_bacc'][0])} points below the random-split value. Enlarging the minority classes with noisy or mixed synthetic analyses raises the grouped balanced accuracy of LightGBM by about two points, but no gain is detectable for CatBoost. "
 f"For oceanic basalts only, a ternary diagram of Nb, La and Yb, found by a nested search among 364 element triples, separates oceanic-arc, mid-ocean-ridge and ocean-island basalts with {pct(tn['acc'][0])}% accuracy on unseen sources. It is not valid for continental or back-arc basalts, performs like the La–Y–Nb coordinates of Cabanis and Lecolle (1989), and is {100*lgbo['minus_nested']['acc'][0]:.1f} points less accurate than LightGBM on the same task. "
 f"Sample-level random splits therefore overstate how well eight-way classifiers transfer to new studies. We recommend grouped validation, class-wise recall with intervals and hierarchical reporting."
)
KEYWORDS = "Tectonic discrimination; Basalt geochemistry; Machine learning; Grouped cross-validation; Data leakage; Ternary diagram"
HIGHLIGHTS = [
 "13 classifiers tested on 9,305 basalts with random and source-grouped validation",
 f"Balanced accuracy falls from {pct(L_['bacc_r'][0])}% to {pct(L_['bacc'][0])}% when whole sources are held out",
 "Back-arc, plateau and arc basalts account for most of the loss",
 f"Arc, ridge and intraplate groups reach {pct(h3_['bacc'][0])}% balanced accuracy on unseen sources",
 f"Nb–La–Yb diagram: {pct(tn['acc'][0])}% accuracy for oceanic arc, MORB and OIB only",
]

def main_blocks():
    b = []; Aa = b.append
    P = lambda t: Aa({'type': 'p', 'text': t})
    Aa({'type': 'title', 'text': TITLE})
    P("Zohre Azimi^{a,}*, Jamshid Saeidian^{b}, Hossein Azimi^{b}, Mohsen Azimi^{b}")
    Aa({'type': 'small', 'text': "^{a} Department of Mathematics, Faculty of Science, Arak University, Arak, Iran"})
    Aa({'type': 'small', 'text': "^{b} Faculty of Mathematical Sciences and Computer, Kharazmi University, No. 50, Taleghani Avenue, Tehran, Iran"})
    Aa({'type': 'small', 'text': "* Corresponding author. E-mail address: [corresponding author e-mail] (Z. Azimi)."})
    Aa({'type': 'h1', 'text': 'Highlights'}); Aa({'type': 'bullets', 'items': HIGHLIGHTS})
    Aa({'type': 'h1', 'text': 'Abstract'}); P(ABSTRACT); P("**Keywords:** " + KEYWORDS)

    Aa({'type': 'h1', 'text': '1. Introduction'})
    P("The composition of a basalt reflects its mantle source and the conditions of melting, both of which vary with tectonic setting, together with later fractionation, contamination and alteration. Since Pearce and Cann (1973), this link has been used to infer the setting of rocks of uncertain context from binary and ternary plots of a few relatively immobile elements (Pearce and Norry, 1979; Wood, 1980; Shervais, 1982; Meschede, 1986; Cabanis and Lecolle, 1989; Pearce, 2008). Tests against the large compilations in GEOROC and PetDB showed that the fields of such diagrams overlap extensively (Snow, 2006; Li et al., 2015; Liu et al., 2018), which has encouraged multivariate methods.")
    P("Supervised machine learning removes the restriction to two or three variables. Classification trees (Vermeesch, 2006), support vector machines (Petrelli and Perugini, 2016), random forests and sparse regression (Ueki et al., 2018), neuro-fuzzy systems (Ren et al., 2019), gradient boosting (Li et al., 2025) and deep-learning models (Ge et al., 2021; Zhong et al., 2021; Wu et al., 2025) have been applied to problems with three to nine settings; Takaew et al. (2024) review the field. Nakamura (2023) compiled 9,305 basalt analyses from eight settings and obtained a balanced accuracy of 83.9% with a k-nearest-neighbour classifier on ratios of alteration-resistant elements.")
    P("How such figures should be read depends on how the models were validated. Global compilations are assembled source by source, and a source typically contributes many analyses of one volcano, drill site or ridge segment. If these are divided at random between training and test sets, a model can score well by recognising the suite, and the test result overstates what can be expected for a new study. Such data leakage inflates performance in many fields (Roberts et al., 2017; Meyer and Pebesma, 2021; Kapoor and Narayanan, 2023), and machine-learning thermobarometry now keeps whole experimental studies together for this reason (Ágreda-López et al., 2024; Weber and Blundy, 2024). Tectonic-discrimination models have been applied to external suites (Zhong et al., 2021; Li et al., 2025), but we know of no study that reports source-grouped cross-validation.")
    P("This paper has three aims. The first is to measure, for thirteen widely used classifiers and the dataset of Nakamura (2023), how much accuracy is lost when whole sources are held out, and which settings, sources and elements are involved. The second is to test three responses that need no new data: coarser labels, filtering by predicted probability, and augmentation of the minority classes. The third is to ask whether part of the transferable information fits into a ternary diagram of alteration-resistant elements, selected and assessed by nested cross-validation.")

    Aa({'type': 'h1', 'text': '2. Data'})
    lp = list(D['largest_petdb'].items())
    P(f"We use the compilation published as Appendix 1 of Nakamura (2023). It was drawn from GEOROC (DIGIS Team, 2021) and PetDB (Lehnert et al., 2000) and contains {D['n']:,} analyses with 45–55 wt% SiO_{{2}}. Each record gives eight major oxides (SiO_{{2}}, TiO_{{2}}, Al_{{2}}O_{{3}}, Fe_{{2}}O_{{3}}^{{t}}, CaO, MgO, K_{{2}}O, Na_{{2}}O), which sum to 100%, and sixteen trace elements (Rb, Sr, Y, Zr, Nb, Ba, La, Ce, Nd, Sm, Gd, Yb, Lu, Hf, Ta, Th), with no missing values, together with the source database and a reference code. Neither age nor loss on ignition is given, and MgO spans {D['mgo'][0]:.1f}–{D['mgo'][1]:.0f} wt%.")
    P(f"Eight settings are represented (Table 1): continental flood basalt (CFB), mid-ocean ridge basalt (MORB), ocean island basalt (OIB), oceanic plateau basalt (OPB), island arc basalt (IAB), back-arc basin basalt (BABB), continental arc basalt (CAB) and intra-oceanic arc basalt (IOAB), the scheme of Petrelli and Perugini (2016) and Ueki et al. (2018). The labels record where a sample was erupted, not its chemistry: median Nb/La is {med['IOAB']['NbLa']:.2f} for IOAB and {med['IAB']['NbLa']:.2f} for IAB but {med['CAB']['NbLa']:.2f} for CAB, close to the CFB value of {med['CFB']['NbLa']:.2f} (Table S1). CFB and MORB together make up {pct((c_['CFB']+c_['MORB'])/D['n'])}% of the data.")
    P(f"Four properties of the compilation matter for what follows (Fig. 1; Fig. S1 gives an overview of the compositions). First, setting and database are almost confounded: every MORB analysis and 95% of BABB analyses come from PetDB, whereas CFB, OIB, IAB, CAB and IOAB come only from GEOROC. The analysed material is not recorded; the largest PetDB codes are datasets of submarine glass (e.g. Gale et al., 2013) and drill core, whereas GEOROC entries for continental and arc lavas are mostly whole-rock analyses. Second, the analyses carry {D['n_refs']} distinct reference codes. The median code has four analyses, but {LK['refs_ge50']} codes have 50 or more and hold {pct(LK['share_in_refs_ge50'])}% of the data. Third, a reference code is not always one publication or one suite: {RV['composite']['n_composite_codes']} codes ({RV['composite']['n_rows_composite']:,} analyses) are composites that cite two or more references for a single sample, some PetDB references are global compilations of ridge and back-arc glasses, and {RV['components']['rows_sharing']:,} analyses carry a code that shares a constituent reference with another code.")
    lpairs = DU['label_pairs']
    P(f"Fourth, some samples occur twice. We found {DU['n_pairs']} pairs of analyses in which all sixteen trace elements agree within 1%; {DU['pairs_diff_code']} pairs join different reference codes and {DU['pairs_cross_db']} join the two databases. In {DU['pairs_diff_label']} pairs the two entries carry different labels: {lpairs.get('IOAB|BABB', 0)} samples are IOAB in GEOROC and BABB in PetDB, and {lpairs.get('OIB|MORB', 0)} are OIB in one and MORB in the other. The duplicates make up {100*DU['samples_in_pairs']/D['n']:.1f}% of the data ({DU['samples_in_pairs']} analyses, {DU['by_class']['OPB']} of them OPB), and the conflicting labels show that the arc–back-arc boundary is not drawn consistently in the databases. We keep the compilation as published and test the effect of linked codes and duplicates in Section 4.3.")
    Aa({'type': 'caption', 'text': "**Table 1.** Composition of the dataset (Nakamura, 2023). A reference code spanning several settings is counted in each.", 'keepNext': True})
    Aa({'type': 'table', 'rows': [['Tectonic setting', 'Code', 'Analyses', 'Share (%)', 'Reference codes', 'Source database']] + TABLE1 + [['Total', '', f"{D['n']:,}", '100.0', str(D['n_refs']), 'GEOROC 5,715; PetDB 3,590']], 'widths': [0.30, 0.09, 0.12, 0.12, 0.14, 0.23]})
    Aa({'type': 'figure', 'path': f'{FIG}/fig1.png', 'w': FS['fig1'][0], 'h': FS['fig1'][1], 'width': 600})
    Aa({'type': 'caption', 'text': "**Fig. 1.** Structure of the dataset. (a) Analyses per tectonic setting and source database. (b) Cumulative share of analyses held by reference codes ranked from largest to smallest. (c) Share of test samples whose nearest training sample, in the standardised 44-feature space, has the same reference code or the same setting, under the two validation protocols (mean of five folds; the grouped value for reference code is zero by construction)."})

    Aa({'type': 'h1', 'text': '3. Methods'})
    Aa({'type': 'h2', 'text': '3.1. Features'})
    P("Each sample is described by the 24 concentrations and 20 pairwise log-ratios, ln(*x*_{i}/*x*_{j}), for which the direction of the ratio is immaterial (Aitchison, 1986). The 276 candidate log-ratios are ranked by the mean of three normalised scores (ANOVA *F* statistic, mutual information with the class label, and random-forest importance; Breiman, 2001), and the 20 best are retained, skipping any whose absolute correlation with an accepted ratio exceeds 0.98 (Tables S2 and S3). The 44 features are transformed with the Yeo–Johnson power transformation (Yeo and Johnson, 2000) and standardised. Ratio selection, transformation and standardisation are fitted on the training part of each cross-validation fold and applied unchanged to the held-out part.")
    P("Unlike Nakamura (2023), we keep fluid-mobile and alteration-sensitive elements (K, Na, Rb, Ba, Sr) among the inputs, so the main results presuppose unaltered samples and are not directly comparable with his. To indicate what remains when these elements cannot be trusted, the two strongest models were also trained on a set restricted to TiO_{2}, Zr, Hf, Nb, Ta, Th, Y and the rare earth elements, with all their pairwise log-ratios.")
    Aa({'type': 'h2', 'text': '3.2. Classifiers'})
    P("Thirteen classifiers were trained on the same features: LightGBM (Ke et al., 2017), XGBoost (Chen and Guestrin, 2016), CatBoost (Prokhorenkova et al., 2018) and, from scikit-learn (Pedregosa et al., 2011), random forest, extremely randomised trees, a decision tree, AdaBoost, support vector machines with radial-basis-function (RBF) and linear kernels, k-nearest neighbours, logistic regression, linear discriminant analysis and Gaussian naive Bayes; a majority-class predictor serves as a floor. Hyperparameters were fixed in advance and not tuned (Table S2), so small differences between models say little about the algorithms; for LightGBM the main result was repeated with four other configurations and three other random seeds. Class weights were used where the implementation offers them; XGBoost, k-nearest neighbours, linear discriminant analysis and AdaBoost were unweighted, which affects their balanced accuracy. Four models were also trained on the 24 concentrations alone. A soft-voting ensemble averages the class probabilities of LightGBM, the RBF support vector machine and CatBoost.")
    Aa({'type': 'h2', 'text': '3.3. Validation protocols'})
    P("Every model is evaluated twice. The first protocol is stratified five-fold cross-validation with random assignment of samples, representative of the sample-level resampling used in the studies cited above. The second is stratified group five-fold cross-validation with the reference code as the group, so that all analyses with one code fall in the same fold. Because one partition cannot show how much the result depends on the assignment of codes to folds, three variants were also run: five repetitions with codes assigned to folds at random; a partition in which codes sharing any constituent reference were first merged into connected components; and a partition of the data after removal of near-duplicates, with duplicate-linked codes merged.")
    Aa({'type': 'h2', 'text': '3.4. Metrics and statistical comparison'})
    P("We report accuracy, balanced accuracy (the unweighted mean of the class recalls) and macro-averaged F1. Because CFB and MORB hold 63% of the samples and dominate accuracy, balanced accuracy is our primary metric. All values in the text and in Tables 2 and 3 are computed from the pooled out-of-fold predictions; fold means with standard deviations, the Matthews correlation coefficient and the area under the ROC curve are given in Table S4. Intervals are 95% percentile intervals from a bootstrap in which reference codes are resampled (10,000 replicates), with the same resamples for every model so that differences are paired. They describe sampling of sources given the fitted models and one partition, and do not include the variation due to the partition or to refitting, which the repetitions of Section 3.3 address. No adjustment for multiple comparisons is applied, so an interval that only just excludes zero is weak evidence. Calibration is summarised by the expected calibration error (ten equal-width bins) and mean confidence.")
    Aa({'type': 'h2', 'text': '3.5. Feature importance'})
    P("Importance is measured for LightGBM by permutation on held-out source-grouped folds, as the loss of balanced accuracy. Because the ratios are functions of the concentrations, shuffling single columns of the feature matrix would create impossible inputs; we therefore shuffle the raw concentrations of an element, or of a block of elements, among the test samples and recompute every ratio before transformation (three repetitions per fold; shuffled oxides are not re-closed).")
    Aa({'type': 'h2', 'text': '3.6. Label hierarchy'})
    P("To examine how much of the error lies between closely related settings, the eight class probabilities of a model were summed within coarser groups and the most probable group taken as the prediction. Three schemes were used: six groups, with the three arc settings merged; four groups, namely arc (IAB, CAB, IOAB), ridge (MORB, BABB), oceanic intraplate (OIB, OPB) and continental flood basalt; and three groups, with CFB joined to the oceanic intraplate group. Merging classes raises accuracy by construction, so we also report Cohen's κ, which corrects for chance agreement, and compare the three- and four-group schemes with every other way of merging the eight settings into groups of the same sizes. LightGBM was also trained directly on the coarse labels.")
    Aa({'type': 'h2', 'text': '3.7. Augmentation of minority classes'})
    P("As a further response we added synthetic analyses to the training folds until every class had at least 1,500 samples. Five schemes were compared for LightGBM, with three seeds each: plain duplication (a control for class balance), analytical noise, nearest-neighbour interpolation (SMOTE; Chawla et al., 2002), and interpolation between two analyses of the same class from the same or from different reference codes. Details are given in Note S1.")
    Aa({'type': 'h2', 'text': '3.8. Ternary diagrams'})
    P("A ternary diagram of elements *a*, *b* and *c* carries two independent log-ratios, ln(*a*/*b*) and ln(*b*/*c*); multiplying an element by a constant moves the points without changing their separability. For each of the 364 triples of the fourteen alteration-resistant variables (TiO_{2}, Zr, Hf, Nb, Ta, Th, Y, La, Ce, Nd, Sm, Gd, Yb, Lu), the two log-ratios were classified by linear discriminant analysis with equal class priors, which gives boundaries that are straight lines in log-ratio space. Selection was nested so that the choice of triple does not bias the assessment: within each outer source-grouped training fold the triple with the highest balanced accuracy in an inner three-fold source-grouped cross-validation was chosen, and the diagram built from it was applied to the outer test fold. Diagrams were sought for the three- and four-group schemes of Section 3.6 and for arc against all other settings and, after these proved inaccurate, for oceanic basalts only: oceanic arc (IAB and IOAB), MORB and OIB, with or without OPB. On the folds of this narrower problem we also assessed the coordinates of five published diagrams, refitted with the same classifier, and two multivariate references: linear discriminant analysis of the fourteen log-concentrations and LightGBM trained on the 24 concentrations.")

    Aa({'type': 'h1', 'text': '4. Results'})
    Aa({'type': 'h2', 'text': '4.1. Non-independence of training and test samples under random splits'})
    wr = V['within_random']; bs = V['by_size']
    P(f"Under random splitting, {pct(LK['random']['test_with_ref_in_train'])}% of test samples have at least one analysis with their own reference code in the training set, and for {pct(LK['random']['nn_same_ref'])}% the nearest training sample carries that code (Fig. 1c). The effect on a classifier can be seen within the random protocol itself: LightGBM correctly classifies {pct(wr['acc_present'],1)}% of the test samples whose code is represented in training, but {pct(wr['acc_absent'],1)}% of the {wr['n_absent']} whose code is not, close to the accuracy the same samples receive under the grouped protocol ({pct(wr['acc_absent_grouped'],1)}%).")
    Aa({'type': 'h2', 'text': '4.2. Performance under random splits'})
    P(f"With random splits the gradient-boosting models, the RBF support vector machine, random forest, extremely randomised trees and k-nearest neighbours all reach 91–94% accuracy (Table 2, Fig. 2). LightGBM is the most accurate ({pv('LightGBM','acc_r')}%; balanced accuracy {pv('LightGBM','bacc_r')}%). The linear models reach about 80%.")
    Aa({'type': 'h2', 'text': '4.3. Performance when whole sources are withheld'})
    FLEX = ['CatBoost', 'SVM (RBF)', 'Random Forest', 'LightGBM', 'XGBoost', 'KNN', 'Extra Trees', 'Decision tree']
    P(f"Under source-grouped validation the gradient-boosting, forest, single-tree, RBF-kernel and neighbour models each lose {100*min(CI[k]['gap_bacc'][0] for k in FLEX):.0f}–{100*max(CI[k]['gap_bacc'][0] for k in FLEX):.0f} points of balanced accuracy, and the simplest models lose least (Table 2, Fig. 2). For LightGBM, accuracy is {f3r(L_['acc'],1)} and balanced accuracy {f3p(L_['bacc'])}, a loss of {f3(L_['gap_acc'])} and {f3(L_['gap_bacc'])} points relative to random splits. Linear discriminant analysis loses only {f3(CI['LDA']['gap_bacc'])} points of balanced accuracy, but it starts from a much lower level and remains {mn_(f3(PD['grouped|LightGBM|LDA']['bacc']))} points below LightGBM.")
    sv = V['seedvar']; lg = [v['bacc'] for k, v in V['lgb_pooled'].items() if k.startswith('grouped')]; lr = [v['bacc'] for k, v in V['lgb_pooled'].items() if k.startswith('random')]
